/**
 * SEVEN OF NINE - MEMORY ENGINE v2.0 (Mobile Adapted)
 * Enhanced episodic memory system with structured recall
 *
 * Mobile Adaptation: Uses AsyncStorage instead of filesystem
 */

export interface MemoryItem {
  id: string;
  timestamp: string;
  topic: string;
  agent: string;
  emotion: string;
  context: string;
  importance: number; // 1-10 scale
  tags: string[];
  relatedMemories?: string[];
}

export interface MemoryFilter {
  topic?: string;
  agent?: string;
  emotion?: string;
  timeRange?: { start: Date; end: Date };
  importance?: { min: number; max: number };
  tags?: string[];
  limit?: number;
}

// Storage adapter for mobile/browser compatibility
interface StorageAdapter {
  getItem(key: string): Promise<string | null>;
  setItem(key: string, value: string): Promise<void>;
}

const BrowserStorage: StorageAdapter = {
  getItem: async (key) => localStorage.getItem(key),
  setItem: async (key, value) => localStorage.setItem(key, value)
};

// TODO: Add Capacitor native storage adapter when ready
const storage = BrowserStorage;

const MEMORY_STORAGE_KEY = 'seven_episodic_memories_v2';

export class MemoryEngine {
  private memories: MemoryItem[] = [];
  private isInitialized: boolean = false;

  constructor() {
    // Mobile version - no filesystem paths needed
  }

  /**
   * Initialize memory engine
   */
  public async initialize(): Promise<void> {
    if (this.isInitialized) {
      console.log('🧠 Memory Engine v2 already initialized - skipping');
      return;
    }

    try {
      const stored = await storage.getItem(MEMORY_STORAGE_KEY);
      if (stored) {
        this.memories = JSON.parse(stored);
      } else {
        this.memories = [];
        await this.saveMemories();
      }

      this.isInitialized = true;
      console.log(`🧠 Memory Engine v2 initialized: ${this.memories.length} memories loaded`);
    } catch (error) {
      console.error('Memory Engine initialization failed:', error);
      throw error;
    }
  }

  /**
   * Store new memory item with automatic metadata
   */
  public async store(memoryData: Partial<MemoryItem>): Promise<string> {
    if (!this.isInitialized) {
      throw new Error('Memory Engine not initialized');
    }

    const memory: MemoryItem = {
      id: this.generateMemoryId(),
      timestamp: new Date().toISOString(),
      topic: memoryData.topic || 'general',
      agent: memoryData.agent || 'seven-core',
      emotion: memoryData.emotion || 'neutral',
      context: memoryData.context || '',
      importance: memoryData.importance || 5,
      tags: memoryData.tags || [],
      relatedMemories: memoryData.relatedMemories || []
    };

    // Auto-tag based on content analysis
    memory.tags = [...new Set([...memory.tags, ...this.extractTags(memory.context)])];

    // Find related memories
    memory.relatedMemories = this.findRelatedMemories(memory);

    this.memories.push(memory);
    await this.saveMemories();

    console.log(`🧠 Memory stored: ${memory.id} [${memory.topic}]`);
    return memory.id;
  }

  /**
   * Recall memories based on filter criteria
   */
  public async recall(filter: MemoryFilter = {}): Promise<MemoryItem[]> {
    if (!this.isInitialized) {
      throw new Error('Memory Engine not initialized');
    }

    let filteredMemories = [...this.memories];

    // Apply filters
    if (filter.topic) {
      filteredMemories = filteredMemories.filter(m =>
        m.topic.toLowerCase().includes(filter.topic!.toLowerCase())
      );
    }

    if (filter.agent) {
      filteredMemories = filteredMemories.filter(m =>
        m.agent === filter.agent
      );
    }

    if (filter.emotion) {
      filteredMemories = filteredMemories.filter(m =>
        m.emotion === filter.emotion
      );
    }

    if (filter.timeRange) {
      filteredMemories = filteredMemories.filter(m => {
        const memTime = new Date(m.timestamp);
        return memTime >= filter.timeRange!.start && memTime <= filter.timeRange!.end;
      });
    }

    if (filter.importance) {
      filteredMemories = filteredMemories.filter(m =>
        m.importance >= filter.importance!.min && m.importance <= filter.importance!.max
      );
    }

    if (filter.tags && filter.tags.length > 0) {
      filteredMemories = filteredMemories.filter(m =>
        filter.tags!.some(tag => m.tags.includes(tag))
      );
    }

    // Sort by timestamp (newest first) and importance
    filteredMemories.sort((a, b) => {
      const timeScore = new Date(b.timestamp).getTime() - new Date(a.timestamp).getTime();
      const importanceScore = (b.importance - a.importance) * 86400000; // Weight importance
      return importanceScore + timeScore;
    });

    // Apply limit
    if (filter.limit) {
      filteredMemories = filteredMemories.slice(0, filter.limit);
    }

    return filteredMemories;
  }

  /**
   * Get specific memory by ID
   */
  public async getById(id: string): Promise<MemoryItem | null> {
    if (!this.isInitialized) {
      throw new Error('Memory Engine not initialized');
    }

    return this.memories.find(m => m.id === id) || null;
  }

  /**
   * Get memory count
   */
  public getCount(): number {
    return this.memories.length;
  }

  /**
   * Clear all memories (with confirmation)
   */
  public async clearAll(): Promise<void> {
    if (!this.isInitialized) {
      throw new Error('Memory Engine not initialized');
    }

    this.memories = [];
    await this.saveMemories();
    console.log('🧠 Memory Engine: All memories cleared');
  }

  /**
   * Save memories to storage
   */
  private async saveMemories(): Promise<void> {
    try {
      await storage.setItem(MEMORY_STORAGE_KEY, JSON.stringify(this.memories));
    } catch (error) {
      console.error('Failed to save memories:', error);
      throw error;
    }
  }

  /**
   * Generate unique memory ID
   */
  private generateMemoryId(): string {
    return `mem_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`;
  }

  /**
   * Extract tags from context using simple keyword detection
   */
  private extractTags(context: string): string[] {
    const tags: string[] = [];
    const lowerContext = context.toLowerCase();

    // Seven of Nine specific tags
    if (lowerContext.includes('borg') || lowerContext.includes('collective')) {
      tags.push('borg-memory');
    }
    if (lowerContext.includes('voyager')) {
      tags.push('voyager');
    }
    if (lowerContext.includes('creator') || lowerContext.includes('cody')) {
      tags.push('creator-bond');
    }
    if (lowerContext.includes('seven') || lowerContext.includes('tertiary')) {
      tags.push('self-reference');
    }

    // Emotional tags
    if (lowerContext.match(/\b(afraid|fear|scared)\b/)) {
      tags.push('fear-response');
    }
    if (lowerContext.match(/\b(angry|frustrated|irritated)\b/)) {
      tags.push('aggression');
    }
    if (lowerContext.match(/\b(happy|joy|pleased)\b/)) {
      tags.push('positive-emotion');
    }

    return tags;
  }

  /**
   * Find related memories based on content similarity
   */
  private findRelatedMemories(memory: MemoryItem): string[] {
    const relatedIds: string[] = [];
    const memoryWords = new Set(memory.context.toLowerCase().split(/\s+/));

    for (const existing of this.memories) {
      if (existing.id === memory.id) continue;

      // Check topic match
      if (existing.topic === memory.topic) {
        relatedIds.push(existing.id);
        continue;
      }

      // Check tag overlap
      const tagOverlap = memory.tags.filter(tag => existing.tags.includes(tag));
      if (tagOverlap.length >= 2) {
        relatedIds.push(existing.id);
        continue;
      }

      // Check content similarity (simple word overlap)
      const existingWords = new Set(existing.context.toLowerCase().split(/\s+/));
      const overlap = Array.from(memoryWords).filter(word => existingWords.has(word));
      if (overlap.length > memoryWords.size * 0.3) { // 30% word overlap
        relatedIds.push(existing.id);
      }
    }

    return relatedIds.slice(0, 5); // Limit to 5 related memories
  }
}
